// STAGE 1 - Input validation and normalization
const body = $input.first().json.body || $input.first().json;
const required = ['use_case_name', 'business_unit', 'description', 'data_description'];
const missing = required.filter(f => !body[f] || String(body[f]).trim() === '');
if (missing.length > 0) {
  return [{ json: { valid: false, error: 'Missing required fields: ' + missing.join(', '), received: body }}];
}
return [{ json: {
  valid: true,
  submission_id: 'UC-' + Date.now(),
  submitted_at: new Date().toISOString(),
  use_case_name: String(body.use_case_name).trim(),
  business_unit: String(body.business_unit).trim(),
  description: String(body.description).trim(),
  data_description: String(body.data_description).trim(),
  proposed_tool: String(body.proposed_tool || 'Not specified').trim(),
  third_parties: String(body.third_parties || 'None stated').trim(),
  expected_volume: String(body.expected_volume || 'Not specified').trim()
}}];

// Parse Stage 1 LLM output and merge with submission
const submission = $('Validate & Normalize').first().json;
const resp = $input.first().json;
let raw = resp.choices?.[0]?.message?.content || '{}';
raw = String(raw).replace(/```json/gi,'').replace(/```/g,'').trim();
let parsed;
try { parsed = JSON.parse(raw); } catch(e) {
  parsed = { data_classification: 'CONFIDENTIAL', data_types: [], contains_pii: false, contains_npi: false, decision_impact: 'MEDIUM', repeatability: 'MEDIUM', third_party_dependency: false, classification_rationale: 'Fallback - parser could not read model output, defaulted to conservative tier.' };
}
return [{ json: { ...submission, stage1: parsed } }];

// Parse Stage 2 risk output, merge
const prev = $('Parse Classification').first().json;
const resp = $input.first().json;
let raw = resp.choices?.[0]?.message?.content || '{}';
raw = String(raw).replace(/```json/gi,'').replace(/```/g,'').trim();
let parsed;
try { parsed = JSON.parse(raw); } catch(e) {
  parsed = { data_leakage_risk:'MEDIUM', model_bias_risk:'MEDIUM', third_party_risk:'MEDIUM', regulatory_exposure:'MEDIUM', overall_risk_tier:'HIGH', nist_rmf_mapping:{govern:'Logged in AI inventory; ISO accountable.',map:'Context and data flow documented.',measure:'Accuracy and drift to be monitored.',manage:'Residual risk pending ISO acceptance.'}, key_risks:['Parser fallback - manual review required'], recommended_controls:['Manual governance review'], approval_route:'ISO_SIGNOFF' };
}
return [{ json: { ...prev, stage2: parsed } }];

// Parse guidance, assemble final governance record, compute KRI fields
const prev = $('Parse Risk Assessment').first().json;
const resp = $input.first().json;
let raw = resp.choices?.[0]?.message?.content || '{}';
raw = String(raw).replace(/```json/gi,'').replace(/```/g,'').trim();
let guidance;
try { guidance = JSON.parse(raw); } catch(e) {
  guidance = { acceptable_use:['Use only within approved tenant tools.'], prohibited_use:['Do not paste Restricted data into external AI tools.'], prompt_rules:['Never include credentials in prompts.'], data_input_restrictions:'No Restricted data without masking and logging.' };
}
const tier = prev.stage2.overall_risk_tier;
const volMatch = String(prev.expected_volume).match(/\d+/);
const vol = volMatch ? parseInt(volMatch[0]) : 50;
const est_minutes_saved_per_run = tier === 'LOW' ? 8 : tier === 'MEDIUM' ? 5 : 3;
const est_monthly_time_saved_hrs = Math.round((vol * 22 * est_minutes_saved_per_run) / 60);
const est_monthly_cost_saving_usd = est_monthly_time_saved_hrs * 60;
const record = {
  submission_id: prev.submission_id,
  submitted_at: prev.submitted_at,
  decided_at: new Date().toISOString(),
  use_case_name: prev.use_case_name,
  business_unit: prev.business_unit,
  proposed_tool: prev.proposed_tool,
  data_classification: prev.stage1.data_classification,
  contains_pii: prev.stage1.contains_pii,
  contains_npi: prev.stage1.contains_npi,
  decision_impact: prev.stage1.decision_impact,
  repeatability: prev.stage1.repeatability,
  overall_risk_tier: tier,
  data_leakage_risk: prev.stage2.data_leakage_risk,
  model_bias_risk: prev.stage2.model_bias_risk,
  third_party_risk: prev.stage2.third_party_risk,
  regulatory_exposure: prev.stage2.regulatory_exposure,
  nist_rmf_mapping: prev.stage2.nist_rmf_mapping,
  key_risks: prev.stage2.key_risks,
  recommended_controls: prev.stage2.recommended_controls,
  approval_route: prev.stage2.approval_route,
  guidance: guidance,
  kri: { est_monthly_time_saved_hrs, est_monthly_cost_saving_usd, risk_reduction_flag: (prev.stage1.data_classification === 'RESTRICTED' || tier === 'HIGH') }
};
return [{ json: record }];

// Append to local KRI datastore for the dashboard
const record = $input.first().json;
const staticData = $getWorkflowStaticData('global');
if (!staticData.records) staticData.records = [];
staticData.records.push({
  submission_id: record.submission_id,
  decided_at: record.decided_at,
  use_case_name: record.use_case_name,
  business_unit: record.business_unit,
  data_classification: record.data_classification,
  overall_risk_tier: record.overall_risk_tier,
  approval_route: record.approval_route,
  est_monthly_time_saved_hrs: record.kri.est_monthly_time_saved_hrs,
  est_monthly_cost_saving_usd: record.kri.est_monthly_cost_saving_usd,
  risk_reduction_flag: record.kri.risk_reduction_flag
});
if (staticData.records.length > 200) staticData.records = staticData.records.slice(-200);
return [{ json: record }];

