const staticData = $getWorkflowStaticData('global');
const recs = staticData.records || [];
const total = recs.length;
const byTier = { LOW:0, MEDIUM:0, HIGH:0 };
const byClass = { PUBLIC:0, INTERNAL:0, CONFIDENTIAL:0, RESTRICTED:0 };
let pending = 0, totalHrs = 0, totalUsd = 0, riskReduced = 0;
recs.forEach(r => {
  byTier[r.overall_risk_tier] = (byTier[r.overall_risk_tier]||0)+1;
  byClass[r.data_classification] = (byClass[r.data_classification]||0)+1;
  if (r.approval_route !== 'AUTO_APPROVE') pending++;
  totalHrs += r.est_monthly_time_saved_hrs || 0;
  totalUsd += r.est_monthly_cost_saving_usd || 0;
  if (r.risk_reduction_flag) riskReduced++;
});
const rows = recs.slice().reverse().slice(0,15).map(r => `<tr><td>${r.submission_id}</td><td>${r.use_case_name}</td><td>${r.business_unit}</td><td><span class=c-${r.data_classification}>${r.data_classification}</span></td><td><span class=t-${r.overall_risk_tier}>${r.overall_risk_tier}</span></td><td>${r.approval_route}</td><td>${r.est_monthly_time_saved_hrs}h</td></tr>`).join('');
const html = `<!doctype html><html><head><meta charset=utf-8><title>AI Governance KRI Dashboard</title><style>
body{font-family:-apple-system,Segoe UI,Roboto,sans-serif;background:#0b1220;color:#e6edf3;margin:0;padding:32px}
h1{font-size:22px;margin:0 0 4px}.sub{color:#8b97a7;font-size:13px;margin-bottom:24px}
.cards{display:grid;grid-template-columns:repeat(5,1fr);gap:16px;margin-bottom:28px}
.card{background:#121c2e;border:1px solid #1f2c44;border-radius:12px;padding:18px}
.card .k{font-size:12px;color:#8b97a7;text-transform:uppercase;letter-spacing:.5px}
.card .v{font-size:26px;font-weight:700;margin-top:8px}
.grid2{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:28px}
.panel{background:#121c2e;border:1px solid #1f2c44;border-radius:12px;padding:18px}
.panel h3{margin:0 0 14px;font-size:14px;color:#cdd6e2}
.bar{display:flex;align-items:center;gap:10px;margin:8px 0;font-size:13px}
.bar .lbl{width:110px;color:#8b97a7}.bar .track{flex:1;background:#0b1220;border-radius:6px;height:14px;overflow:hidden}
.bar .fill{height:100%;border-radius:6px}
table{width:100%;border-collapse:collapse;font-size:12px}
th,td{text-align:left;padding:9px 10px;border-bottom:1px solid #1f2c44}
th{color:#8b97a7;text-transform:uppercase;font-size:11px;letter-spacing:.5px}
.t-LOW{color:#3fb950}.t-MEDIUM{color:#d29922}.t-HIGH{color:#f85149}
.c-PUBLIC{color:#3fb950}.c-INTERNAL{color:#58a6ff}.c-CONFIDENTIAL{color:#d29922}.c-RESTRICTED{color:#f85149}
.foot{color:#5b6676;font-size:11px;margin-top:20px}
</style></head><body>
<h1>AI Governance KRI Dashboard</h1>
<div class=sub>Live program metrics &middot; NIST AI RMF aligned &middot; ${new Date().toISOString().slice(0,16).replace('T',' ')} UTC</div>
<div class=cards>
<div class=card><div class=k>Use Cases Governed</div><div class=v>${total}</div></div>
<div class=card><div class=k>Pending Approval</div><div class=v style=color:#d29922>${pending}</div></div>
<div class=card><div class=k>High-Risk Tier</div><div class=v style=color:#f85149>${byTier.HIGH}</div></div>
<div class=card><div class=k>Est. Hrs Saved / mo</div><div class=v style=color:#3fb950>${totalHrs}</div></div>
<div class=card><div class=k>Est. $ Saved / mo</div><div class=v style=color:#3fb950>$${totalUsd.toLocaleString()}</div></div>
</div>
<div class=grid2>
<div class=panel><h3>Risk Tier Distribution</h3>
${['LOW','MEDIUM','HIGH'].map(t=>{const c=t==='LOW'?'#3fb950':t==='MEDIUM'?'#d29922':'#f85149';const p=total?Math.round(byTier[t]/total*100):0;return `<div class=bar><span class=lbl>${t}</span><span class=track><span class=fill style="width:${p}%;background:${c}"></span></span><span>${byTier[t]}</span></div>`}).join('')}
</div>
<div class=panel><h3>Data Classification</h3>
${['PUBLIC','INTERNAL','CONFIDENTIAL','RESTRICTED'].map(t=>{const c=t==='PUBLIC'?'#3fb950':t==='INTERNAL'?'#58a6ff':t==='CONFIDENTIAL'?'#d29922':'#f85149';const p=total?Math.round(byClass[t]/total*100):0;return `<div class=bar><span class=lbl>${t}</span><span class=track><span class=fill style="width:${p}%;background:${c}"></span></span><span>${byClass[t]}</span></div>`}).join('')}
</div>
</div>
<div class=panel><h3>Recent Governance Decisions</h3>
<table><tr><th>ID</th><th>Use Case</th><th>Unit</th><th>Data Class</th><th>Risk</th><th>Routing</th><th>Saved</th></tr>${rows||'<tr><td colspan=7 style=color:#5b6676>No submissions yet - POST a use case to /webhook/ai-usecase-intake</td></tr>'}</table></div>
<div class=foot>Risk-reduction-flagged use cases: ${riskReduced} &middot; Generated by AI Governance Pipeline (n8n) &middot; Illustrative KRI estimates</div>
</body></html>`;
return [{ json: { html } }];
